package com.eightbittrade.clipforge;
import android.content.*;
import android.net.Uri;
import android.media.*;
import android.provider.MediaStore;
import android.os.Environment;
import java.io.*;
import java.nio.*;
import java.util.*;
public class VideoTools {
 public static class Meta {public double duration;public int width,height;public float fps=30;}
 public static Meta inspect(File file)throws Exception {Meta m=new Meta();MediaMetadataRetriever r=new MediaMetadataRetriever();try{r.setDataSource(file.getPath());m.duration=Double.parseDouble(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION))/1000;int w=Integer.parseInt(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH)),h=Integer.parseInt(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT));String rot=r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION);boolean swap="90".equals(rot)||"270".equals(rot);m.width=swap?h:w;m.height=swap?w:h;}finally{r.release();}
  MediaExtractor e=new MediaExtractor();try{e.setDataSource(file.getPath());for(int i=0;i<e.getTrackCount();i++){MediaFormat f=e.getTrackFormat(i);if(f.getString(MediaFormat.KEY_MIME).startsWith("video/")){if(f.containsKey(MediaFormat.KEY_FRAME_RATE))m.fps=f.getInteger(MediaFormat.KEY_FRAME_RATE);if(f.containsKey(MediaFormat.KEY_COLOR_TRANSFER)){int transfer=f.getInteger(MediaFormat.KEY_COLOR_TRANSFER);if(transfer==MediaFormat.COLOR_TRANSFER_ST2084||transfer==MediaFormat.COLOR_TRANSFER_HLG)throw new IOException("This is an HDR video. Please choose an SDR original for this Android preview release.");}}}}finally{e.release();}return m;
 }
 public static void mux(File video,File audio,File output)throws Exception{MediaMuxer mux=new MediaMuxer(output.getPath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);List<MediaExtractor> sources=new ArrayList<>();List<Integer> targets=new ArrayList<>();try{for(File source:Arrays.asList(video,audio)){MediaExtractor e=new MediaExtractor();sources.add(e);e.setDataSource(source.getPath());String kind=source.equals(video)?"video/":"audio/";boolean found=false;for(int i=0;i<e.getTrackCount();i++){MediaFormat f=e.getTrackFormat(i);if(f.getString(MediaFormat.KEY_MIME).startsWith(kind)){e.selectTrack(i);targets.add(mux.addTrack(f));found=true;break;}}if(!found)throw new IOException("YouTube did not provide a compatible "+kind+" track.");}mux.start();ByteBuffer buffer=ByteBuffer.allocateDirect(16*1024*1024);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();for(int n=0;n<sources.size();n++){MediaExtractor e=sources.get(n);while(true){buffer.clear();int count=e.readSampleData(buffer,0);if(count<0)break;info.set(0,count,e.getSampleTime(),(e.getSampleFlags()&MediaExtractor.SAMPLE_FLAG_SYNC)!=0?MediaCodec.BUFFER_FLAG_KEY_FRAME:0);mux.writeSampleData(targets.get(n),buffer,info);e.advance();}}mux.stop();}finally{for(MediaExtractor e:sources)e.release();mux.release();}}
 public static Uri save(Context ctx,File file)throws Exception{ContentValues v=new ContentValues();v.put(MediaStore.Video.Media.DISPLAY_NAME,"ClipForge-"+System.currentTimeMillis()+".mp4");v.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");v.put(MediaStore.Video.Media.RELATIVE_PATH,Environment.DIRECTORY_MOVIES+"/ClipForge");v.put(MediaStore.Video.Media.IS_PENDING,1);ContentResolver resolver=ctx.getContentResolver();Uri uri=resolver.insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,v);if(uri==null)throw new IOException("Gallery could not create a video entry.");try(InputStream input=new FileInputStream(file);OutputStream output=resolver.openOutputStream(uri)){if(output==null)throw new IOException("Gallery output could not be opened.");byte[] copyBuffer=new byte[65536];int copied;while((copied=input.read(copyBuffer))!=-1)output.write(copyBuffer,0,copied);v.clear();v.put(MediaStore.Video.Media.IS_PENDING,0);resolver.update(uri,v,null,null);return uri;}catch(Exception e){resolver.delete(uri,null,null);throw e;}}
}
